<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Order; use App\Models\OrderItem; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ReportController extends Controller { public function sales(Request $r){$from=$r->date('from')?->startOfDay()??now()->startOfMonth();$to=$r->date('to')?->endOfDay()??now()->endOfDay();$base=Order::whereBetween('created_at',[$from,$to]);$stats=['orders'=>(clone $base)->count(),'revenue'=>(float)(clone $base)->whereNotIn('status',['cancelled'])->sum('total'),'paid'=>(float)(clone $base)->where('payment_status','paid')->sum('total'),'delivered'=>(clone $base)->where('status','delivered')->count()];$daily=Order::selectRaw('DATE(created_at) day, COUNT(*) orders, SUM(total) revenue')->whereBetween('created_at',[$from,$to])->whereNotIn('status',['cancelled'])->groupBy('day')->orderBy('day')->get();$top=OrderItem::select('product_name')->selectRaw('SUM(quantity) qty, SUM(line_total) sales')->whereHas('order',fn($q)=>$q->whereBetween('created_at',[$from,$to])->whereNotIn('status',['cancelled']))->groupBy('product_name')->orderByDesc('qty')->limit(10)->get();return view('admin.reports.sales',compact('from','to','stats','daily','top'));} }
